"use strict";

const fs = require("node:fs");
const path = require("node:path");

// Mimics the parts of the Rollup bundle API the observer reads: chunks carry
// per-module renderedLength, and write appends bytes the generated code lacks.
function render(chunks) {
  return {
    output: [
      ...chunks.map((chunk) => ({ type: "chunk", fileName: chunk.fileName, code: chunk.code, modules: chunk.modules })),
      { type: "asset", fileName: "style.css", source: "body{}" },
    ],
  };
}

async function rollup(inputOptions) {
  return {
    cache: undefined,
    async generate() {
      return render(inputOptions.chunks);
    },
    async write(outputOptions) {
      const result = render(inputOptions.chunks);
      const dir = outputOptions.dir ? path.resolve(outputOptions.dir) : path.dirname(path.resolve(outputOptions.file));
      fs.mkdirSync(dir, { recursive: true });
      for (const item of result.output) {
        const data = item.type === "chunk" ? `${item.code}\n//# sourceMappingURL=${item.fileName}.map\n` : item.source;
        fs.writeFileSync(path.join(dir, item.fileName), data);
      }
      return result;
    },
    async close() {},
  };
}

module.exports = { rollup, VERSION: "0.0.0-fake" };
